def prime_fib(n: int) -> int:
    def is_prime(num: int) -> bool:
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def fibonacci_generator():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    fib_gen = fibonacci_generator()
    prime_fibs = []
    for _ in range(n):
        fib_num = next(fib_gen)
        while not is_prime(fib_num):
            fib_num = next(fib_gen)
        prime_fibs.append(fib_num)

    return prime_fibs[-1]
